  q(".app-back").addEventListener("click", function(){ setView(S.from); });

  // cube setup, driven by the mapping from the Unity scene
  var draw = q(".cfg-draw"), stage = q(".cfg-draw-stage"), emptyMsg = q(".setup-empty"), pill = q("[data-orient-pill]");
  function fitDraw(){ var box = draw.parentNode, w = box.clientWidth, h = box.clientHeight; if (!w) return; var s = Math.min(w / 570, (h || 1e9) / 520); draw.style.width = (570 * s) + "px"; stage.style.transform = "scale(" + s + ")"; }
  if (window.ResizeObserver) new ResizeObserver(fitDraw).observe(draw.parentNode);
